from lib import *
S = SS('p64')
steps = [
    step("本机服务器、16 个线程抓 2000 个 URL(服务器延迟:90% 在 5–15 ms,8% 在 30–80 ms,2% 是长尾),总耗时 3.55 秒:平均 23.7 ms,中位数 12.8 ms,p90 26.2 ms,p95 63.0 ms,p99 266.5 ms,最大 1532 ms。平均值是中位数的 1.8 倍,90% 的请求低于平均值。只报平均值会让人以为“一个请求 24 ms”,而一半的请求在 13 ms 以内,1% 的请求要 267 ms 以上。", t=tl(S(1)), done=lidx(S(1), '总耗时'), b=bars([['中位数 ms', 12.8, '12.8'], ['平均 ms', 23.7, '23.7'], ['p95 ms', 63.0, '63.0'], ['p99 ms', 266.5, '266.5'], ['最大 ms', 1532, '1532']], 1600, done=[0], mark=[3, 4]), kv=KV([['中位数', '12.8 ms'], ['平均', '23.7 ms(1.8 倍)'], ['p99', '266.5 ms']], ['p99'])),
    step("同一批数据,不同算法的分位数不一样。取前 100 个:p99 最近排名法 83.4 ms、statistics.quantiles 的 inclusive(线性插值)83.5 ms、exclusive 96.9 ms;p95 分别是 50.3、50.6、55.8 ms。取全部 2000 个:p99 为 266.5、266.5、270.6 ms;p95 为 63.0、63.0、63.1 ms。样本多时算法的差别可以忽略;样本少时 exclusive 比另外两种高十几个百分点,报告时要说明用的哪种。", t=tl(S(2)), done=lidx(S(2), '取前  100 个'), mark=lidx(S(2), '取前 2000 个'), b=bars([['100 个:p99 最近排名', 83.4, '83.4'], ['100 个:p99 inclusive', 83.5, '83.5'], ['100 个:p99 exclusive', 96.9, '96.9']], 100, done=[0, 1], mark=[2]), kv=KV([['100 个样本', 'exclusive 的 p99 高 13 ms'], ['2000 个样本', '三种算法差 4 ms 以内'], ['做法', '报告里写明算法']], ['100 个样本'])),
    step("样本少时 p99 很不稳定(从同一个分布生成延迟,每个样本量重复 1000 次,p99 的 5%–95% 范围):用 40 万个样本估计的“真实”p99 约 305 ms;每次 100 个样本:64–629 ms,中位 172 ms;每次 1000 个:160–462 ms,中位 297 ms;每次 10000 个:260–358 ms,中位 305 ms。100 个请求算出的 p99 可能差 10 倍,一小时内只抓了几百个请求的 p99 并不可靠。", t=tl(S(3)), done=lidx(S(3), '每次   100 个样本'), mark=lidx(S(3), '每次 10000 个样本'), b=bars([['100 个样本:p99 范围上界 ms', 629, '629'], ['1000 个样本:p99 范围上界 ms', 462, '462'], ['10000 个样本:p99 范围上界 ms', 358, '358'], ['真实 p99 ms', 305, '305']], 650, mark=[0], done=[3]), kv=KV([['100 个样本', '64–629 ms'], ['1000 个样本', '160–462 ms'], ['10000 个样本', '260–358 ms']], ['100 个样本'])),
    step("几个 worker 各自算 p99 再平均,和合在一起算不一样(合成数据,4 个 worker 各抓 4000、2000、1000、200 个请求,最后一个更慢):各 worker 的 p99 是 322、327、623、1109 ms,直接平均 595 ms;合在一起算 p99 366 ms;按请求数加权平均 387 ms。每个 worker 只上报直方图:桶很粗时(10 个桶,边界 5…5000 ms)合并估计 p99 为 500 ms(桶上界);换成更细的 19 个桶估计 400 ms;精确值 366 ms。分位数不能平均,要上报原始样本或直方图再合并,桶的粒度决定误差。", t=tl(S(4)), done=lidx(S(4), '合在一起算 p99'), mark=lidx(S(4), '各 worker 的 p99'), b=bars([['各 worker p99 直接平均 ms', 595, '595'], ['按请求数加权 ms', 387, '387'], ['合并 19 个桶估计 ms', 400, '400'], ['精确 p99 ms', 366, '366']], 620, mark=[0], done=[3]), kv=KV([['平均各 worker 的 p99', '595 ms'], ['合在一起算', '366 ms'], ['粗桶合并估计', '500 ms,细桶 400 ms']], ['合在一起算'])),
    step("超时请求的延迟记不记?客户端 timeout=0.2 秒,同样 2000 个 URL:28 个 ReadTimeout,记下的耗时中位 201 ms(被 timeout 截断)。含超时的全部 2000 个请求 p99 为 201 ms;只统计成功的 1847 个请求 p99 为 78 ms;真实的 p99(不设 timeout)是 267 ms。三个数字说的是三件事:含超时的被 timeout 封顶,只算成功的把最慢的那批全丢了。", t=tl(S(5)), done=lidx(S(5), '全部 2000 个请求'), mark=lidx(S(5), '超时 28 个'), b=bars([['只统计成功请求 p99 ms', 78, '78'], ['含超时(截断在 timeout)p99 ms', 201, '201'], ['真实 p99(不设 timeout)ms', 267, '267']], 280, mark=[0, 1], done=[2]), kv=KV([['只算成功请求', 'p99 78 ms(最慢的被丢掉了)'], ['含超时', 'p99 201 ms(被 timeout 封顶)'], ['不设 timeout', 'p99 267 ms']], ['含超时'])),
    step("“成功率”的算法:2000 个请求里状态码 200 的占 94.8%(1895 个)、503 有 105 个;200 且正文非空的占 93.7%(1874 个)——服务器对 1% 的 URL 固定返回 200 + 空正文。每 200 个一个窗口:96、95、92、96、90、95、93、92、92、96(%),波动 90–96。对第一次失败的 126 个 URL 各重试一次:成功 57 个,最终成功率 96.5%,多发 6.3% 的请求;仍失败的 69 个里 67 个是我在服务器里设定的“按 URL 固定会失败”的。只看状态码会把空正文算成成功;重试能挽回的是随机失败,救不了固定失败。", t=tl(S(6)), done=lidx(S(6), '对失败的 126 个 URL'), mark=lidx(S(6), '状态码分布'), b=bars([['状态码 200 的占比 %', 94.8, '94.8'], ['200 且正文非空 %', 93.7, '93.7'], ['重试一次后的最终成功率 %', 96.5, '96.5']], 100, mark=[0], done=[2]), kv=KV([['只看状态码', '94.8%'], ['要求正文非空', '93.7%'], ['重试 1 次', '96.5%,多发 6.3% 请求']], ['要求正文非空'])),
]
A = mkartp('p64', 64, '爬虫,监控,指标,延迟分位数,p99,成功率,直方图,Python,真实验证,动画演示',
    '在本机服务器上抓 2000 个 URL 实测:平均值是中位数的 1.8 倍;不同分位数算法在小样本时差十几个百分点;100 个样本的 p99 可以差 10 倍;worker 各自的 p99 不能平均;超时封顶会让 p99 失真;只看状态码会把空正文算成成功。',
    '爬虫上线后要看指标:成功率多少、延迟多少。但平均值、分位数、成功率各有几种算法,算错了会得出完全不同的结论。这篇用一个本机服务器把这几个坑逐个量出来。',
    [('12.8 对 266.5 ms', '2000 个请求的延迟中位数与 p99(平均值 23.7 ms)'), ('64–629 ms', '只有 100 个样本时 p99 的 5%–95% 范围(同一个分布,真实 p99 约 305 ms)'), ('595 对 366 ms', '各 worker 的 p99 直接平均 与 合在一起算的 p99(合成数据)')],
    [('平均值会骗人', '<p>延迟分布通常是一堆很快的请求加一小撮很慢的。平均值被长尾拉高:实验里平均 23.7 ms,中位数 12.8 ms,90% 的请求低于平均值。看 p95、p99 才能看到长尾。</p>'),
     ('分位数的算法', '<p>同一批 100 个数据,p99 用最近排名法和 statistics.quantiles 的 inclusive 差不多(83 ms),exclusive 是 96.9 ms;2000 个数据时三种差在 4 ms 以内。样本少时要写明算法。</p>'),
     ('样本量', '<p>样本少时分位数本身就不稳定。同一个分布,100 个样本的 p99 在 64–629 ms 之间,1000 个样本是 160–462 ms,10000 个样本才收敛到 260–358 ms。统计窗口太短、请求太少时,p99 的抖动大多是噪声。</p>'),
     ('不能平均分位数', '<p>多个 worker 各自的 p99 求平均没有意义:负载小的 worker 权重被放大(实验里平均出 595 ms,真实是 366 ms)。要上报原始值或直方图再合并;直方图的桶越粗,合并后的估计误差越大(500 ms 对 366 ms)。这一节是合成数据,不是真实请求。</p>'),
     ('超时的请求怎么算', '<p>被 timeout 截断的请求,耗时就是 timeout 本身。含上它们,p99 被封顶在 201 ms;只算成功的,把最慢的请求都丢了,p99 只有 78 ms;真实值(不设 timeout)是 267 ms。报告里要同时给出超时的比例。</p>'),
     ('成功率', '<p>只看状态码 200 会把“200 但正文为空”算成功(94.8% 对 93.7%)。成功率还要说清是“第一次请求成功率”还是“重试之后每个 URL 的最终成功率”:重试一次把 93.7% 提到 96.5%,多发 6.3% 的请求,而固定失败的 URL 重试也救不回来(第 30 篇的退避、第 32 篇的分类讲过重试策略)。</p>')],
    steps,
    [ENV_P + '。服务器是本机的 Srv(延迟按 URL 编号用固定随机数确定;2% 的 URL 固定 503、1% 的 URL 固定返回 200 加空正文,每次请求另有 3% 的随机 503),客户端是 requests Session + 16 个线程;第一、二、五、六节用真实请求(各一次);第三、四节是用同一个延迟分布生成的合成数据(第三节每个样本量重复 1000 次)',
     '没有验证:真实站点的延迟分布(它们常常比这个更偏、有多个峰);更高的并发下客户端自身排队造成的延迟(coordinated omission:延迟从请求发出算起,没有包含等待发出的时间);Prometheus、HdrHistogram 等工具的分位数实现;滑动窗口里的 p99 怎么高效计算;时间序列上的告警阈值'],
    '爬虫指标')
